{
  "resourceType": "StructureDefinition",
  "id": "SzPatient",
  "url": "{{hapi_base_url}}/fhir/StructureDefinition/SzPatient",
  "version": "0.1.1",
  "name": "EswatiniPatient",
  "title": "Eswatini Patient Profile",
  "status": "active",
  "publisher": "MoH Eswatini",
  "description": "Definition of the FHRI Eswatini Patient resource",
  "fhirVersion": "4.0.1",
  "kind": "resource",
  "abstract": false,
  "type": "Patient",
  "baseDefinition": "http://hl7.org/fhir/StructureDefinition/Patient",
  "derivation": "constraint",
  "differential": {
    "element": [
      {
        "id": "Patient.extension",
        "path": "Patient.extension",
        "slicing": {
          "discriminator": [
            {
              "type": "value",
              "path": "url"
            }
          ],
          "ordered": false,
          "rules": "open"
        }
      },
      {
        "id": "Patient.extension:nationality",
        "path": "Patient.extension",
        "sliceName": "nationality",
        "short": "Nationality.",
        "definition": "Patient's nationality according to ID document",
        "min": 0,
        "max": "*",
        "type": [
          {
            "code": "Extension",
            "profile": [
              "http://hl7.org/fhir/StructureDefinition/patient-nationality"
            ]
          }
        ]
      },
      {
        "id": "Patient.extension:inkhundla",
        "path": "Patient.extension",
        "sliceName": "inkhundla",
        "min": 0,
        "max": "1",
        "type": [
          {
            "code": "Extension",
            "profile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzInkhundlaExtension"
            ]
          }
        ],
        "mustSupport": true
      },
      {
        "id": "Patient.extension:chiefdom",
        "path": "Patient.extension",
        "sliceName": "chiefdom",
        "min": 0,
        "max": "1",
        "type": [
          {
            "code": "Extension",
            "profile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzChiefdomExtension"
            ]
          }
        ],
        "mustSupport": true
      },
      {
        "id": "Patient.identifier",
        "path": "Patient.identifier",
        "short": "Patient's Identification Number",
        "min": 1
      },
      {
        "id": "Patient.identifier.type",
        "path": "Patient.identifier.type",
        "short": "Type of Identifier",
        "min": 1
      },
      {
        "id": "Patient.identifier.type.coding.code",
        "path": "Patient.identifier.type.coding.code",
        "binding": {
          "strength": "required",
          "valueSet": "{{hapi_base_url}}/fhir/ValueSet/PersonIdentifiersVS"
        }
      },
      {
        "id": "Patient.identifier.value",
        "path": "Patient.identifier.value",
        "short": "Value of the identification number",
        "min": 1
      },
      {
        "id": "Patient.name",
        "path": "Patient.name",
        "short": "Patient's name",
        "definition": "Verified  Patient's name",
        "min": 1,
        "max": "1",
        "mustSupport": true
      },
      {
        "id": "Patient.name.family",
        "path": "Patient.name.family",
        "definition": "Patient's family name",
        "min": 1
      },
      {
        "id": "Patient.name.given",
        "path": "Patient.name.given",
        "short": "Patient's given name",
        "definition": "Patient's given name",
        "min": 1
      },
      {
        "id": "Patient.gender",
        "path": "Patient.gender",
        "short": "Sex at birth: male | female | other | unknown",
        "definition": "Identifier to determine the genetic, endocrine and morphological characteristics of the body at birth.",
        "min": 1
      },
      {
        "id": "Patient.birthDate",
        "path": "Patient.birthDate",
        "short": "Date of birth: YYYY-MM-DD",
        "min": 1,
        "mustSupport": true
      },
      {
        "id": "Patient.birthDate.extension",
        "path": "Patient.birthDate.extension",
        "slicing": {
          "discriminator": [
            {
              "type": "value",
              "path": "url"
            }
          ],
          "ordered": false,
          "rules": "open"
        },
        "short": "Patient's birth time."
      },
      {
        "id": "Patient.birthDate.extension:birthTime",
        "path": "Patient.birthDate.extension",
        "sliceName": "birthTime",
        "min": 0,
        "max": "1",
        "type": [
          {
            "code": "Extension",
            "profile": [
              "http://hl7.org/fhir/StructureDefinition/patient-birthTime"
            ]
          }
        ]
      },
      {
        "id": "Patient.address",
        "path": "Patient.address",
        "mustSupport": true
      },
      {
        "id": "Patient.address.city",
        "path": "Patient.address.city",
        "mustSupport": true
      },
      {
        "id": "Patient.address.country",
        "path": "Patient.address.country",
        "mustSupport": true
      }
    ]
  }
}

