{
  "resourceType": "StructureDefinition",
  "id": "SzLabResult",
  "url": "{{hapi_base_url}}/fhir/StructureDefinition/SzLabResult",
  "name": "SzLabResult",
  "title": "Eswatini Lab Result Profile",
  "status": "draft",
  "description": "Eswatini Lab Result Profile",
  "fhirVersion": "4.0.1",
  "kind": "resource",
  "abstract": false,
  "type": "Observation",
  "baseDefinition": "http://hl7.org/fhir/StructureDefinition/Observation",
  "derivation": "constraint",
  "differential": {
    "element": [
      {
        "id": "Observation.extension",
        "path": "Observation.extension",
        "slicing": {
          "discriminator": [
            {
              "type": "value",
              "path": "url"
            }
          ],
          "ordered": false,
          "rules": "open"
        },
        "min": 2
      },
      {
        "id": "Observation.extension:authorizer",
        "path": "Observation.extension",
        "sliceName": "authorizer",
        "short": "Lab results authorizer",
        "definition": "Lab technician who authorized the lab results",
        "min": 1,
        "max": "1",
        "type": [
          {
            "code": "Extension",
            "profile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzAuthorizerExtension"
            ]
          }
        ],
        "mustSupport": true
      },
      {
        "id": "Observation.extension:testingLaboratory",
        "path": "Observation.extension",
        "sliceName": "testingLaboratory",
        "short": "Testing laboratory",
        "definition": "Laboratory who performed the test",
        "min": 1,
        "max": "1",
        "type": [
          {
            "code": "Extension",
            "profile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzTestingLabExtension"
            ]
          }
        ],
        "mustSupport": true
      },
      {
        "id": "Observation.code",
        "path": "Observation.code",
        "short": "Local test parameter code",
        "mustSupport": true,
        "binding": {
          "strength": "required",
          "valueSet": "{{hapi_base_url}}/fhir/ValueSet/SzTestParameterCodeVS"
        }
      },
      {
        "id": "Observation.subject",
        "path": "Observation.subject",
        "short": "Patient profile",
        "definition": "The patient this observation is about",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPatient"
            ]
          }
        ]
      },
      {
        "id": "Observation.encounter",
        "path": "Observation.encounter",
        "short": "Encounter",
        "definition": "The encounter/visit this observation was made",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzEncounter"
            ]
          }
        ]
      },
      {
        "id": "Observation.performer",
        "path": "Observation.performer",
        "definition": "Lab Technician who performed the test",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPractitioner"
            ]
          }
        ]
      },
      {
        "id": "Observation.value[x]",
        "path": "Observation.value[x]",
        "min": 1,
        "mustSupport": true
      },
      {
        "id": "Observation.specimen",
        "path": "Observation.specimen",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzLabSpecimen"
            ]
          }
        ]
      }
    ]
  }
}

{
  "resourceType": "StructureDefinition",
  "id": "SzLabSpecimen",
  "url": "{{hapi_base_url}}/fhir/StructureDefinition/SzLabSpecimen",
  "version": "0.1.0",
  "name": "EswatiniSpecimenProfile",
  "title": "Eswatini Specimen Profile",
  "status": "active",
  "publisher": "Ministry of Health Eswatini",
  "contact": [
    {
      "name": "Health Management Information Systems (HMIS)",
      "telecom": [
        {
          "value": "800 600 5"
        }
      ]
    }
  ],
  "description": "The Eswatini Specimen Profile is based on the FHIR Specimen resource. This profile sets minimum\nexpectation for Specimen resource to record information about substances associated with a patient or laboratory request being tested.\nThis profile specifies which core elements shall be present and how these elements are used.",
  "fhirVersion": "4.0.1",
  "kind": "resource",
  "abstract": false,
  "type": "Specimen",
  "baseDefinition": "http://hl7.org/fhir/StructureDefinition/Specimen",
  "derivation": "constraint",
  "differential": {
    "element": [
      {
        "id": "Specimen",
        "path": "Specimen",
        "short": "Eswatini Health Information Exchange Specimen Profile"
      },
      {
        "id": "Specimen.type",
        "path": "Specimen.type",
        "short": "Type of specimen being collected",
        "min": 1,
        "mustSupport": true,
        "binding": {
          "strength": "preferred",
          "valueSet": "http://terminology.hl7.org/CodeSystem/v2-0487"
        }
      },
      {
        "id": "Specimen.subject",
        "path": "Specimen.subject",
        "short": "Patient associated with the specimen being collected",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPatient"
            ]
          }
        ]
      },
      {
        "id": "Specimen.collection",
        "path": "Specimen.collection",
        "short": "Specimen collection information",
        "definition": "Date and Time of specimen collection and the person who collected the specimen",
        "min": 1
      },
      {
        "id": "Specimen.collection.collector",
        "path": "Specimen.collection.collector",
        "short": "Specimen collector",
        "min": 1,
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPractitioner"
            ]
          }
        ],
        "mustSupport": true
      },
      {
        "id": "Specimen.collection.collected[x]",
        "path": "Specimen.collection.collected[x]",
        "short": "Specimen collection date",
        "min": 1,
        "type": [
          {
            "code": "dateTime"
          }
        ],
        "mustSupport": true
      }
    ]
  }
}

{
  "resourceType": "StructureDefinition",
  "id": "SzLabTest",
  "url": "{{hapi_base_url}}/fhir/StructureDefinition/SzLabTest",
  "version": "0.1.1",
  "name": "EswatiniLabTest",
  "title": "Eswatini Lab Test Profile",
