        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPatient"
            ]
          }
        ]
      },
      {
        "id": "DiagnosticReport.encounter",
        "path": "DiagnosticReport.encounter",
        "short": "Encounter information",
        "definition": "Encounter relevant to the requested lab order",
        "min": 1,
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzEncounter"
            ]
          }
        ]
      },
      {
        "id": "DiagnosticReport.effective[x]",
        "path": "DiagnosticReport.effective[x]",
        "short": "Lab request date",
        "definition": "Date and time when the order was requested",
        "min": 1,
        "mustSupport": true
      },
      {
        "id": "DiagnosticReport.performer",
        "path": "DiagnosticReport.performer",
        "short": "Lab test requestor",
        "definition": "Clinician who performed the lab order",
        "min": 1,
        "max": "1",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPractitioner"
            ]
          }
        ],
        "mustSupport": true
      },
      {
        "id": "DiagnosticReport.specimen",
        "path": "DiagnosticReport.specimen",
        "short": "Lab test specimen",
        "definition": "Specimen relevant to the order being reqested",
        "min": 1,
        "max": "1",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzLabSpecimen"
            ]
          }
        ],
        "mustSupport": true
      }
    ]
  }
}

{
