{
  "resourceType": "StructureDefinition",
  "id": "SzVitalSigns",
  "url": "{{hapi_base_url}}/fhir/StructureDefinition/SzVitalSigns",
  "version": "0.1.0",
  "name": "EswatiniVitalSigns",
  "title": "Eswatini Vital Signs Profile",
  "status": "active",
  "publisher": "Ministry of Health Eswatini",
  "contact": [
    {
      "name": "Health Management Information Systems (HMIS)",
      "telecom": [
        {
          "value": "800 600 5"
        }
      ]
    }
  ],
  "description": "This profile is based on the base FHIR Vital Signs Profile and defines additional constraints on the Observation resource to represent\nvital signs observations specifically for Eswatini.",
  "fhirVersion": "4.0.1",
  "kind": "resource",
  "abstract": false,
  "type": "Observation",
  "baseDefinition": "http://hl7.org/fhir/StructureDefinition/vitalsigns",
  "derivation": "constraint",
  "differential": {
    "element": [
      {
        "id": "Observation",
        "path": "Observation",
        "short": "Eswatini Health Information Exchange Vital Signs"
      },
      {
        "id": "Observation.code",
        "path": "Observation.code",
        "short": "Specific vital sign being observed",
        "binding": {
          "strength": "required",
          "valueSet": "http://hl7.org/fhir/ValueSet/observation-vitalsignresult"
        }
      },
      {
        "id": "Observation.subject",
        "path": "Observation.subject",
        "short": "Patient related to the vitals being recorded",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPatient"
            ]
          }
        ]
      },
      {
        "id": "Observation.value[x]",
        "path": "Observation.value[x]",
        "type": [
          {
            "code": "Quantity"
          }
        ]
      },
      {
        "id": "Observation.value[x].value",
        "path": "Observation.value[x].value",
        "min": 1
      },
      {
        "id": "Observation.value[x].unit",
        "path": "Observation.value[x].unit",
        "min": 1,
        "mustSupport": true
      },
      {
        "id": "Observation.value[x].system",
        "path": "Observation.value[x].system",
        "short": "Units of measure for the vital sign being observed",
        "min": 1,
        "patternUri": "http://unitsofmeasure.org",
        "mustSupport": true
      },
      {
        "id": "Observation.value[x].code",
        "path": "Observation.value[x].code",
        "min": 1,
        "mustSupport": true,
        "binding": {
          "strength": "required",
          "valueSet": "http://unitsofmeasure.org"
        }
      }
    ]
  }
}

{
  "resourceType": "StructureDefinition",
  "id": "SzEncounter",
  "url": "{{hapi_base_url}}/fhir/StructureDefinition/SzEncounter",
  "version": "0.1.0",
  "name": "EswatiniEncounter",
  "title": "Eswatini Encounter Profile",
  "status": "active",
  "publisher": "Ministry of Health Eswatini",
  "contact": [
    {
      "name": "Health Management Information Systems (HMIS)",
      "telecom": [
        {
          "value": "800 600 5"
        }
      ]
    }
  ],
  "description": "The Eswatini Encounter Profile inherits from .... This profile sets minimum expectations for the Encounter resource to record basic encounter\ninformation for a patient. It specifies which core elements shall be present and constrains how the elements are used.",
  "fhirVersion": "4.0.1",
  "kind": "resource",
  "abstract": false,
  "type": "Encounter",
  "baseDefinition": "http://hl7.org/fhir/StructureDefinition/Encounter",
  "derivation": "constraint",
  "differential": {
    "element": [
      {
        "id": "Encounter",
        "path": "Encounter",
        "short": "Eswatini Health Information Exchange Encounter"
      },
      {
        "id": "Encounter.class",
        "path": "Encounter.class",
        "short": "Department in which the encounter took place",
        "mustSupport": true,
        "binding": {
          "strength": "required",
          "valueSet": "{{hapi_base_url}}/fhir/ValueSet/SzEncounterClassificationVS"
        }
      },
      {
        "id": "Encounter.subject",
        "path": "Encounter.subject",
        "short": "Patient associated with the encounter",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPatient"
            ]
          }
        ]
      },
      {
        "id": "Encounter.participant",
        "path": "Encounter.participant",
        "min": 1,
        "max": "1",
        "mustSupport": true
      },
      {
        "id": "Encounter.participant.individual",
        "path": "Encounter.participant.individual",
        "short": "Clinicians who participated in the encounter",
        "type": [
          {
            "code": "Reference",
            "targetProfile": [
              "{{hapi_base_url}}/fhir/StructureDefinition/SzPractitioner"
            ]
          }
        ]
      },
      {
        "id": "Encounter.reasonCode",
        "path": "Encounter.reasonCode",
        "short": "Service Point",
        "definition": "Service points the patient has visited: HTS | ART | ANC etc",
